#include <iostream>
#include <vector>
using namespace std;

const long long MOD = 1000000007LL;

long long mod_pow(long long base, long long exp) {
    long long result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % MOD;
        }
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long x, n;
    cin >> x >> n;

    vector<long long> primes;
    long long temp_x = x;
    for (long long p = 2; p * p <= temp_x; ++p) {
        if (temp_x % p == 0) {
            primes.push_back(p);
            while (temp_x % p == 0) {
                temp_x /= p;
            }
        }
    }
    if (temp_x > 1) {
        primes.push_back(temp_x);
    }

    long long answer = 1;
    for (long long p : primes) {
        long long sum_exponents = 0;
        unsigned long long current_power = p;
        while (current_power <= (unsigned long long)n) {
            sum_exponents += n / current_power;
            if (current_power > (unsigned long long)n / p) break;
            current_power *= p;
        }
        answer = (answer * mod_pow(p, sum_exponents)) % MOD;
    }

    cout << answer << endl;
    return 0;
}
